import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as i,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Action Group Guide","description":"Crossing from reading the world to writing it: tool-calling contract and tool-execution engineering — how actions are described, validated, and executed safely.","frontmatter":{"title":"Action Group Guide","description":"Crossing from reading the world to writing it: tool-calling contract and tool-execution engineering — how actions are described, validated, and executed safely.","domain":"tech","tags":["tech","action","navigation"],"navOrder":49,"topicId":"action-guide","layer":"5","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":[],"next":["tool-calling","tool-execution"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/05-action/index.md","filePath":"tech/05-action/index.md","lastUpdated":1791165915000}'),r={name:"tech/05-action/index.md"};function n(l,e,s,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="action-group-guide" tabindex="-1">Action Group Guide <a class="header-anchor" href="#action-group-guide" aria-label="Permalink to &quot;Action Group Guide&quot;">​</a></h1><blockquote><p><strong>Group</strong>: Action (writing the world) | <strong>Previous group exit</strong>: answers grounded in traceable evidence | <strong>This group exit</strong>: define one controlled action with idempotency, timeout, cancellation, and permission boundaries</p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>BLUF</strong>: systems up to the Grounding group at worst give an unsupported answer. Starting here, systems <strong>change the external world</strong> — writing files, sending messages, placing orders. The worst failure upgrades from &quot;wrong answer&quot; to &quot;wrong action&quot;, often irreversible. This group is two pages answering one question: <strong>how to keep an action under control</strong>.</p><table tabindex="0"><thead><tr><th>Page</th><th>Question it answers</th><th>You leave able to</th></tr></thead><tbody><tr><td><a href="./tool-calling.html">Tool calling contract</a></td><td>How does the model <em>intend</em> an action? Schema, selection, argument validation</td><td>Define reliable tool interface contracts</td></tr><tr><td><a href="./tool-execution.html">Tool execution engineering</a></td><td>How is <em>actual execution</em> safe? Idempotency, timeouts, cancellation, side-effect classes, permissions</td><td>Ship a controlled executor</td></tr></tbody></table><p><strong>Boundary</strong>: this group is the single-action primitive layer. Multi-step orchestration and state move to <a href="./../06-agent-systems/">Agent Systems</a>; cross-boundary protocols to <a href="./../07-interoperability/">Interoperability</a>.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><ul><li>Want the <strong>contract</strong> shape for model tool calls → start at <a href="./tool-calling.html">Tool calling contract</a>.</li><li>Already calling tools but worried about <strong>duplicate runs, hangs, privilege escape</strong> → read <a href="./tool-execution.html">Tool execution engineering</a> directly.</li><li>Both pages ship a zero-key runnable fixture; run it first, then read.</li></ul><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>The intent/execution split organizes this group and is its security foundation: model output is only <strong>intent</strong> (structured arguments); execution authority stays entirely in your code. Every safeguard — validation, allowlists, idempotency keys, approval gates — lives on the execution side.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>Common pitfalls: overly permissive tool schemas (all-optional arguments, vague descriptions) degrade intent quality; missing side-effect classification treats irreversible operations like ordinary calls. Each page&#39;s Development section carries the matching runbooks.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><ul><li>Beginner: <a href="./tool-calling.html">Tool calling contract</a> overview and decision table.</li><li>Builder: the execution-loop fixture in <a href="./tool-execution.html">Tool execution engineering</a>.</li><li>Operator: execution runbooks (timeout, cancellation, approval).</li><li>Researcher: Anthropic / OpenAI official tool-use guides (see each page&#39;s resource tables).</li></ul>',14)])])}const b=t(r,[["render",n]]);export{f as __pageData,b as default};
